import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from ridgeline ----
// Synthetic hourly CPU utilization across a fleet of server clusters, one point per hour.
// Seeded generator, not real telemetry. Clusters are ordered by peak hour so the ridges
// sweep left to right across the day, the effect a ridgeline plot is built to show.

const HOURS = 24;

function mulberry32(seed: number): () => number {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const CLUSTER_NAMES = [
  'ap-southeast-cache',
  'ap-southeast-web',
  'ap-northeast-api',
  'eu-central-batch',
  'eu-central-api',
  'eu-west-web',
  'eu-west-db',
  'us-east-api',
  'us-east-web',
  'us-east-db',
  'us-central-batch',
  'us-west-cache',
  'us-west-api',
  'us-west-web'
];

const random = mulberry32(0x5210);

type UtilizationSeries = { name: string; peakHour: number; values: number[] };

const clusterUtilization: UtilizationSeries[] = CLUSTER_NAMES.map((name, i) => {
  // Regional clusters peak near local daytime; spread peaks across the day with jitter.
  const peakHour = ((i / CLUSTER_NAMES.length) * 24 + random() * 4) % 24;
  const amplitude = 35 + random() * 40;
  const baseline = 8 + random() * 10;
  const spread = 2.5 + random() * 2;

  const values = Array.from({ length: HOURS }, (_, hour) => {
    // Circular distance so the bump wraps across midnight.
    const delta = Math.min(Math.abs(hour - peakHour), 24 - Math.abs(hour - peakHour));
    const bump = amplitude * Math.exp(-(delta * delta) / (2 * spread * spread));
    const noise = (random() - 0.5) * 4;
    return Math.max(0, baseline + bump + noise);
  });

  return { name, peakHour, values };
}).sort((a, b) => a.peakHour - b.peakHour);

const ROW_HEIGHT = 24;
// How many row-steps a ridge may rise into the rows above it before flattening.
const OVERLAP = 3.4;
const MARGIN = { top: 90, right: 20, bottom: 30, left: 150 };

/** One row per series, each holding a value for every hour of the day, top row first. */
export type Data = { name: string; values: number[] }[];

export default function RidgelinePlot({
  data = clusterUtilization,
  width
}: {
  data?: Data;
  width: number;
}) {
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = data.length * ROW_HEIGHT;
  const height = innerHeight + MARGIN.top + MARGIN.bottom;

  const { rows, xTicks } = useMemo(() => {
    const x = d3
      .scaleLinear()
      .domain([0, 23])
      .range([0, Math.max(innerWidth, 0)]);

    const y = d3
      .scalePoint<string>()
      .domain(data.map((d) => d.name))
      .range([0, innerHeight]);

    const z = d3
      .scaleLinear()
      .domain([0, d3.max(data, (d) => d3.max(d.values)) ?? 0])
      .nice()
      .range([0, -OVERLAP * y.step()]);

    const color = d3.scaleSequential(d3.interpolateCool).domain([0, data.length - 1]);

    const area = d3
      .area<number>()
      .curve(d3.curveBasis)
      .x((_, i) => x(i))
      .y0(0)
      .y1((d) => z(d));
    const line = area.lineY1();

    return {
      rows: data.map((d, i) => ({
        name: d.name,
        offset: (y(d.name) ?? 0) + 1,
        fill: area(d.values) ?? undefined,
        stroke: line(d.values) ?? undefined,
        color: color(i)
      })),
      xTicks: x.ticks(Math.min(12, innerWidth / 60)).map(
        (v): Tick => ({ value: `${v}:00`, offset: x(v) })
      )
    };
  }, [data, innerWidth, innerHeight]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Ridgeline plot of synthetic hourly CPU utilization across 14 server clusters, ordered by peak hour"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {/* Painted top row first: a ridge that rises into the row above is drawn over it. */}
        {rows.map((row) => (
          <g key={row.name} transform={`translate(0,${row.offset})`}>
            <path d={row.fill} fill={row.color} fillOpacity={0.92} />
            <path d={row.stroke} fill="none" stroke="var(--bg)" strokeWidth={1.2} />
          </g>
        ))}
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        {rows.map((row) => (
          <text
            key={row.name}
            x={-10}
            y={row.offset}
            dy="0.32em"
            textAnchor="end"
            fontSize={10}
            fill="var(--muted)"
          >
            {row.name}
          </text>
        ))}
      </g>
    </svg>
  );
}
